// ── Baseline Motion Composer ──
// Monolithic alternative to motion-composer.js — no function composition.
// Each entity config carries an `_updateCode` string generated by the LLM.
// This module lazy-compiles it into a function and assigns it as the primary motion.
// New entities referenced in configs are auto-created.

import { Entity } from './entity.js';

const DANGEROUS = /\b(document|window|fetch|eval|import|require|XMLHttpRequest|globalThis)\b/;

/**
 * Baseline motion resolver — same signature as composeMotions().
 * Runs monolithic _updateCode per entity. No composition fallback —
 * entities without _updateCode simply idle in place.
 * Auto-creates new entities that appear in config but not in the scene.
 */
export function composeMotionsBaseline(entityMap, entityConfigs, stateMachine, bounds, dt) {
  const stateDef = stateMachine.current;

  for (const [name, config] of Object.entries(entityConfigs)) {
    let e = entityMap[name];

    // Auto-create entity if it doesn't exist yet
    if (!e) {
      const cx = bounds.right ?? 512, cy = bounds.bottom ?? 512;
      e = new Entity(
        config.startX ?? cx / 2,
        config.startY ?? cy / 2,
        {
          shape: config.shape || 'circle',
          color: config.color || '#4FC3F7',
          size: config.size || 'medium',
          boundaryBehavior: 'rebound',
        }
      );
      e._name = name;
      entityMap[name] = e;
    }

    // Basic setup (same as composeMotions)
    e._bounds = bounds;
    if (config.target) {
      e._target = entityMap[config.target];
    }
    e._stateDuration = stateDef?.duration ?? 3;

    // If this specific entity has no _updateCode, idle it
    if (!config._updateCode) {
      e.setPrimary({ update() {}, cleanup() {} });
      e.setSecondary(null);
      continue;
    }

    // Lazy-compile _updateCode
    if (!config._compiledUpdate || config._compiledUpdateSource !== config._updateCode) {
      if (DANGEROUS.test(config._updateCode)) {
        console.warn(`[baseline] Disallowed keywords in _updateCode for "${name}", skipping`);
        config._compiledUpdate = null;
        config._compiledUpdateSource = config._updateCode;
      } else {
        try {
          config._compiledUpdate = new Function('entity', 'dt', 'bounds', config._updateCode);
          config._compiledUpdateSource = config._updateCode;
        } catch (err) {
          console.warn(`[baseline] Failed to compile _updateCode for "${name}":`, err);
          config._compiledUpdate = null;
          config._compiledUpdateSource = config._updateCode;
        }
      }
    }

    // Build a motion object from the compiled code
    const compiled = config._compiledUpdate;
    const motion = {
      update(entity, frameDt) {
        if (!compiled) return;
        try {
          compiled(entity, frameDt, bounds);
        } catch (err) {
          console.warn(`[baseline] Runtime error in _updateCode for "${name}":`, err.message);
        }
      },
      cleanup() {},
    };

    e.setPrimary(motion);
    e.setSecondary(null);

    // Apply explicit color override if provided
    if (config.color) {
      e.color = config.color;
    }
  }
}
